(function(w){var a=w.BVC_PASSAGE_RESEARCH_CONTENT=w.BVC_PASSAGE_RESEARCH_CONTENT||[];[{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"1SA_01_01_08_WORBS_READER_DERIVATIVE_v0.1_20261017","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/1SA_01_01_08_WORBS_READER_DERIVATIVE_v0.1_20261017.md","sourceSha256":"439fbba733865477f11397723074a540f642f9b54b811324460dbb5e816f5eb5","passage":{"book":"1sa","chapter":1,"v1":1,"v2":8,"ref":"사무엘상 1:1–8"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"예배의 길 위에 놓인 한나의 눈물","overview":["사무엘상은 왕의 즉위나 전쟁의 승리로 시작하지 않는다. 에브라임 산지의 한 가정, 해마다 실로 성소로 올라가는 가족, 그리고 자녀가 없어 고통받는 한나의 이야기로 문을 연다. 엘가나는 한나를 사랑하지만, 또 다른 아내 브닌나의 지속적인 괴롭힘과 자녀가 없는 현실을 해결하지 못한다. 예배를 드리는 날조차 한나는 울며 먹지 못한다."],"centralMessage":"사무엘상 1:1–8은 이스라엘의 새 시대가 시작될 무대를, 해결되지 않은 한 여성의 고통과 반복되는 예배의 자리에서 마련한다. 하나님의 주권을 고백하는 서술은 한나의 상처를 죄의 결과로 판정하지 않으며, 인간의 위로가 미치지 못하는 자리를 드러낸 뒤 한나가 하나님께 직접 말하게 될 다음 장면을 준비한다.","literaryStructure":[{"v1":1,"v2":2,"title":"왕궁이 아니라 한 가정에서 시작되는 이야기"},{"v1":3,"v2":3,"title":"실로로 올라가는 예배와 아직 드러나지 않은 균열"},{"v1":4,"v2":5,"title":"제물의 몫으로도 메워지지 않는 결핍"},{"v1":6,"v2":7,"title":"예배 때마다 반복되는 상처"},{"v1":8,"v2":8,"title":"사랑하지만 다 알지 못하는 남편의 질문"}],"sections":[{"id":"1sa1-1-2","v1":1,"v2":2,"title":"왕궁이 아니라 한 가정에서 시작되는 이야기","paragraphs":["첫 문장은 에브라임 산지의 라마다임소빔에 사는 엘가나를 소개하고, 그의 조상들을 거슬러 올라간다. 이처럼 인물의 거주지와 가계를 제시하는 방식은 앞으로 일어날 일을 한 가정의 구체적인 역사 속에 놓는다. 그러나 화자가 독자에게 먼저 알려 주는 결정적인 사실은 엘가나의 지위나 재산이 아니다. 그에게 한나와 브닌나라는 두 아내가 있으며, 브닌나에게는 자녀가 있고 한나에게는 없다는 사실이다. 이 대비가 뒤따르는 모든 장면의 정서적 출발점이 된다.","두 아내가 있다는 사실은 고대 사회의 가정 구조를 보여 주지만, 서술이 그 관계를 이상적인 모습으로 칭찬하는 것은 아니다. 오히려 두 사람의 처지가 비교되면서 한 가정 안의 상처와 경쟁이 전면에 나타난다. 창세기에서 사라와 하갈, 레아와 라헬 사이에 나타났던 긴장을 떠올리게 하지만, 인물들의 사정과 행동이 모두 같다고 볼 수는 없다. 이 연결이 중요한 이유는 성경이 출산과 계승의 문제를 다룰 때 인간의 통제 밖에 있는 한계와 그 안에서 벌어지는 관계의 갈등을 함께 보여 준다는 데 있다.","엘가나의 출신지인 라마다임소빔은 본문의 지리적 출발점이다. ‘에브라임 사람’이라는 표현은 이 지역과의 연관을 나타내지만, 그것만으로 그의 혈통 전체를 확정할 수는 없다. 또한 고대 지명을 현대의 특정 지점과 일대일로 대응시키는 데에는 별도의 증거가 필요하다. 본문이 우선 알려 주는 것은 이 가족이 에브라임 산지에서 살았다는 사실이다."]},{"id":"1sa1-3-3","v1":3,"v2":3,"title":"실로로 올라가는 예배와 아직 드러나지 않은 균열","paragraphs":["엘가나는 해마다 자기 성읍에서 실로로 올라가 ‘만군의 여호와’께 경배하고 제사를 드린다. 가족의 삶에는 정기적인 예배의 리듬이 있다. 여기서 ‘올라간다’는 말은 성소를 향한 이동을 서술하며, 본문은 그 순례가 반복되었다는 사실을 강조한다. 출발지와 목적지는 제시되지만 이동 경로, 걸린 시간, 중간 기착지는 기록되지 않는다. 따라서 이 구절을 세밀한 고대 도로 지도로 바꾸기보다, 가족이 일상에서 성소로 나아가는 반복적인 움직임으로 이해하는 것이 적절하다.","‘만군의 여호와’(יְהוָה צְבָאוֹת, 여호와 체바오트)는 여호와의 통치와 권능을 드러내는 호칭이다. 여기서 ‘만군’을 곧바로 이스라엘의 군대 하나로만 좁힐 필요는 없다. 이 호칭은 앞으로 왕과 전쟁, 나라의 운명을 다룰 사무엘상 전체를 내다보게 한다. 그러나 첫 장면에서 그 하나님께 나아가는 사람은 군대를 이끄는 왕이 아니라 자녀가 없어 슬퍼하는 한 여성의 가족이다. 큰 역사를 다스리시는 하나님과 한 사람의 고통이 같은 서사의 첫머리에 놓인 것이다.","화자는 실로에 엘리의 두 아들 홉니와 비느하스가 제사장으로 있었다는 사실도 미리 말한다. 3절만으로 그들의 죄를 모두 알 수는 없지만, 뒤따르는 2장에서는 그들이 제사를 멸시하고 성소를 더럽히는 행위가 드러난다. 그러므로 이 짧은 소개는 성소 자체가 아무 문제 없는 공간이라는 기대를 서서히 흔든다. 한나의 가정에서 일어나는 상처와 제사장 집안의 위기는 아직 다른 장면이지만, 이야기의 진행 속에서 서로를 비추게 된다."]},{"id":"1sa1-4-5","v1":4,"v2":5,"title":"제물의 몫으로도 메워지지 않는 결핍","paragraphs":["제사를 드리는 날 엘가나는 브닌나와 그 자녀들에게 제물의 몫을 나누어 주고 한나에게도 몫을 준다. 이 식사 장면은 가족이 함께 제사에 참여하고 있음을 보여 주면서 동시에 자녀가 있는 사람과 없는 사람의 차이를 다시 드러낸다. 한나를 사랑한다는 엘가나의 마음은 분명하지만, 그 사랑이 곧 한나의 고통을 없애 주지는 못한다.","5절의 히브리어 표현 מָנָה אַחַת אַפָּיִם(마나 아하트 압파임)은 번역이 쉽지 않다. 흔히 한나에게 ‘갑절의 몫’을 주었다고 옮기지만, ‘특별한 몫’이나 ‘한 몫’으로 이해하는 견해도 있다. 따라서 제물의 정확한 양을 확정해 이야기의 의미를 세우는 것은 조심해야 한다. 본문에서 분명한 것은 엘가나가 한나를 사랑했다는 사실과, 그 사랑에도 불구하고 한나의 태가 닫혀 있었다는 사실이다.","서술자는 ‘여호와께서 그의 태를 닫으셨다’고 말한다. 이 표현은 생명이 인간의 뜻대로 주어지는 것이 아니라는 신앙적 인식을 드러낸다. 그러나 한나가 어떤 잘못을 저질렀기 때문에 자녀를 갖지 못했다는 설명은 본문 어디에도 없다. 하나님의 주권을 고백하는 서술을 고통받는 사람에 대한 도덕적 판결로 바꾸면, 본문이 말하지 않는 원인을 만들어 내게 된다."]},{"id":"1sa1-6-7","v1":6,"v2":7,"title":"예배 때마다 반복되는 상처","paragraphs":["브닌나는 한나를 심히 격동시키고 괴롭힌다. 히브리어 צָרָה(차라)는 문맥에 따라 경쟁 상대나 적대적인 처지의 사람을 가리킬 수 있다. 여기서는 같은 남편을 둔 다른 아내가 한나에게 적대적으로 행동하는 관계를 드러낸다. 이어지는 자극과 괴롭힘의 표현은 한나가 단순히 남과 비교하며 속상해한 정도가 아니라, 타인의 의도적인 공격을 겪고 있음을 보여 준다.","7절은 이 일이 ‘매년’ 되풀이되었다고 말한다. 한나의 눈물은 하루의 돌발적인 감정이 아니다. 실로에 올라가는 정기적인 예배의 때마다 괴롭힘이 다시 시작되었고, 그 결과 한나는 울며 먹지 못했다. 제사의 식사가 가족의 기쁨과 교제를 나타낼 수 있는 자리에서, 한나는 그 식사에 참여할 힘마저 잃는다. 성소를 찾는 신앙생활과 깊은 슬픔이 같은 시간에 존재한다는 사실이 이 장면의 긴장이다.","이 대목은 브닌나의 공격을 정당화하지도, 한나의 눈물을 믿음이 부족하다는 표시로 설명하지도 않는다. 서술자는 오히려 상처의 반복을 충분히 보여 줌으로써 다음 장면에서 한나가 왜 자신의 마음을 여호와 앞에 쏟아 놓는지 이해하게 한다. 한나의 기도는 아무 문제 없는 사람이 신앙적 열심을 보이기 위해 덧붙인 행동이 아니라, 오래 지속된 고통 속에서 나오는 말이다."]},{"id":"1sa1-8-8","v1":8,"v2":8,"title":"사랑하지만 다 알지 못하는 남편의 질문","paragraphs":["엘가나는 한나에게 왜 울며 먹지 않고 마음이 슬프냐고 묻는다. 그는 아내의 눈물과 식욕 상실을 알아차린다. 이어 ‘내가 그대에게 열 아들보다 낫지 아니하냐’고 말하며 자신의 사랑으로 한나를 위로하려 한다. ‘열 아들’은 많은 아들을 가리키는 강조 표현으로 읽을 수 있으며, 실제 자녀 수를 세는 정보로 취급할 필요는 없다.","그의 말에는 애정이 담겨 있지만, 한나가 겪는 고통을 충분히 이해하지 못하는 한계도 드러난다. 남편의 사랑은 소중하지만 브닌나의 공격과 자녀가 없다는 현실을 대신 해결해 주지는 못한다. 본문은 엘가나를 악인으로 단정하지 않는다. 동시에 그가 좋은 뜻으로 건넨 말이 한나의 눈물을 멈추게 했다고도 기록하지 않는다.","이렇게 첫 여덟 절은 해결책을 내놓지 않은 채 멈춘다. 독자는 한나의 처지를 알게 되었지만, 아직 한나 자신의 긴 기도를 듣지 못했다. 9절 이후 한나는 일어나 여호와 앞에 나아가며, 자신의 쓰라린 마음을 직접 말한다. 첫 단락의 문학적 역할은 한나의 고통을 서둘러 설명하거나 없애는 데 있지 않다. 그 고통을 있는 그대로 드러내고, 이제 하나님 앞에서 시작될 새로운 대화를 준비하는 데 있다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"‘만군의 여호와’라는 호칭의 기능","paragraphs":["צְבָאוֹת(체바오트)는 ‘군대들’, ‘무리들’과 관련된 말이다. 그 지시 범위를 하나의 군사 조직으로 한정하기보다는 여호와의 광범한 통치권을 드러내는 칭호로 읽는 것이 자연스럽다. 왕정으로 향하는 책의 도입부에 이 이름이 놓였다는 점은 의미가 있지만, 이 한 구절만으로 후대의 왕권 신학 전체가 이미 상세히 전개되었다고 말할 수는 없다."]},{"title":"5절의 제물 분배와 번역의 한계","paragraphs":["מָנָה אַחַת אַפָּיִם의 정확한 뜻에는 논의가 남아 있다. ‘갑절’이라는 익숙한 번역을 유일한 정답으로 삼거나, 반대로 엘가나가 한나를 홀대했다고 결론 내리기 어렵다. 서술이 직접 밝히는 사랑과 한나의 지속되는 슬픔을 함께 읽어야 한다."]},{"title":"하나님의 주권과 인간의 가해를 구별하기","paragraphs":["5–6절의 ‘여호와께서 태를 닫으셨다’는 서술과 브닌나가 한나를 괴롭혔다는 서술은 서로 다른 행위를 말한다. 본문은 한나의 불임을 하나님 주권 아래에 놓지만, 그 사실을 브닌나의 모욕에 대한 정당화로 사용하지 않는다. 또한 고난의 원인을 한나 개인의 죄에서 찾지 않는다. 이 구분은 본문 자체의 인물 평가를 보존하는 데 중요하다."]},{"title":"앞뒤 본문과의 관계","paragraphs":["창세기 29–30장의 레아와 라헬 이야기는 출산과 가족 내 경쟁이 서로 얽힐 때 생기는 긴장을 보여 준다. 사무엘상 1:9–20은 한나가 이 고통을 여호와 앞에 말하고, 1:21–28은 받은 아들을 봉헌하는 과정을 전한다. 사무엘상 2:1–10의 한나의 노래는 개인의 경험을 낮은 자를 높이시고 교만한 자를 낮추시는 하나님의 통치로 확장한다. 이 뒤의 내용을 첫 여덟 절에 미리 모두 집어넣기보다, 첫 장면이 제기한 질문이 어떻게 전개되는지를 따라 읽는 편이 좋다."]}],"relatedResearch":[],"readerSources":[],"notes":["성경 본문: 대한성서공회, 『성경전서 개역한글판』, 사무엘상 1:1–8; 창세기 16장, 29–30장; 사무엘상 1:9–2:10. 히브리어 표현은 사무엘상 1:1–8의 마소라 본문을 기준으로 검토하였다."]}].forEach(function(r){a.push(r);});if(w.JBCResearch&&w.JBCResearch._done)w.JBCResearch._done("1sa");})(window);
